typedef short s16;

class FEMenuEntry {};

struct AdjustorVtable
{
    char pad[448];
    s16 adjustment;
    void (*call)(void*, int);
};

class FEMultiMenu
{
public:
    char pad0[0x4c];
    FEMenuEntry* highlighted;
    char pad1[0x24];
    AdjustorVtable* movement_vtable;

    void OnLeft(int c)
    {
        void* adjusted = (char*)this + movement_vtable->adjustment;
        movement_vtable->call(adjusted, c);
    }
};

struct PanelVtable
{
    char pad[24];
    s16 adjustment;
    void (*turn_on)(void*, bool);
};

class PanelQuad
{
public:
    char pad[404];
    PanelVtable* panel_vtable;

    void TurnOn(bool on)
    {
        void* adjusted = (char*)this + panel_vtable->adjustment;
        panel_vtable->turn_on(adjusted, on);
    }
};

struct MemCard
{
    int free;
    bool exists;
    bool changed;
    bool available;
    bool ask_format;
    bool saved_games;
    int status;
};

class FEManager
{
public:
    char pad[0x15678];
    bool fe_done;
};

extern FEManager frontendmanager;
class entity;
enum EventType { SS_FE_LEFTRIGHT = 26 };

class SoundScriptManager
{
public:
    static SoundScriptManager* s_inst;
    static SoundScriptManager* inst() { return s_inst; }
    void pause();
    void unpause();
    int playEvent(EventType type, entity* e = 0, float fadeInTime = 0);
};

class NamesMenu : public FEMultiMenu
{
public:
    char pad2[0x178 - sizeof(FEMultiMenu)];
    int arrow_num;
    int arrow_counter;
    char pad3[0x1bc - 0x180];
    MemCard cards[2];
    char pad4[12];
    int adjusted_active_card;
    char pad5[8];
    PanelQuad* arrows[2][2];

    static const int arrow_timer = 3;
    void OnCardSwitch();
    void MakeSpaceFreeMessage(int free);
    void OnLeft(int c);
};

void NamesMenu::OnLeft(int c)
{
	FEMenuEntry* initial = highlighted;
#ifdef TARGET_XBOX
	do 
	{
#endif
	FEMenuEntry* before = highlighted;
	FEMultiMenu::OnLeft(c);
	if(before != highlighted)
	{
		OnCardSwitch();
	}
#ifdef TARGET_XBOX
	} while (cards[adjusted_active_card].exists == false);
#endif
	if(initial != highlighted)
	{
		if (frontendmanager.fe_done)
			SoundScriptManager::inst()->unpause();
		SoundScriptManager::inst()->playEvent(SS_FE_LEFTRIGHT);
		if (frontendmanager.fe_done)
				SoundScriptManager::inst()->pause();
		arrows[0][1]->TurnOn(true);
		arrows[0][0]->TurnOn(false);
		arrow_num = 0;
		arrow_counter = arrow_timer;
		cards[adjusted_active_card].changed = true;
/*		if (!cards[adjusted_active_card].available)
			cards[adjusted_active_card].ask_format = true;*/
		MakeSpaceFreeMessage(cards[adjusted_active_card].free);
	}
}
